   "pourquoi_ici": "Ce grand lac offre un vaste dortoir aux oiseaux qui se nourrissent dans les champs alentour. Chaque automne, des dizaines de milliers de grues cendrées y font escale, avec oies, canards et pygargues.",
   "menace": "Très touristique, le lac voit se multiplier les projets d'aménagement ; une fréquentation mal canalisée dérange les oiseaux au nid et en hiver.",
   "ce_qui_marche": "Réserve nationale depuis 1978, le lac est fermé à la chasse ; des dizaines de milliers de grues y passent même l'hiver."
